export { default as PaperCrumple } from './PaperCrumple.vue';
export type {
  PaperCrumpleProps,
  PaperCrumpleState,
  PaperCrumpleRelease,
  PaperCrumpleImageFit,
  PaperCrumpleStatus,
} from './types';

import * as THREE from 'three';
import {
  advance,
  clamp,
  createPaperPath,
  finite,
  randomSource,
  spring,
} from './paper-path';
import type {
  PaperCrumpleEngine,
  PaperCrumpleEngineContext,
  PaperCrumpleState,
  PaperPath,
} from './types';

let pathCache: { key: string; value: PaperPath } | null = null;

const at = (list: ArrayLike<number>, i: number) => list[i] ?? 0;

export function createPaperEngine(
  ctx: PaperCrumpleEngineContext,
): PaperCrumpleEngine | null {
  const { root, canvas, hit, scene: cfg } = ctx;
  ctx.onStatus('loading');
  hit.dataset.held = 'false';
  hit.setAttribute('aria-pressed', 'false');
  const initialRect = root.getBoundingClientRect();
  const paperWidth = Math.max(1, finite(cfg.width, 320));
  const paperHeight = Math.max(1, finite(cfg.height, 400));
  const initialScale = Math.min(
    1,
    Math.max(1, initialRect.width - 48) / paperWidth,
    Math.max(1, initialRect.height - 48) / paperHeight,
  );
  root.style.setProperty('--pc-image-width', `${paperWidth * initialScale}px`);
  root.style.setProperty(
    '--pc-image-height',
    `${paperHeight * initialScale}px`,
  );

  let renderer: THREE.WebGLRenderer;
  try {
    renderer = new THREE.WebGLRenderer({
      canvas,
      alpha: true,
      antialias: true,
      powerPreference: 'low-power',
    });
  } catch (error) {
    ctx.onStatus('error');
    ctx.onError(
      error instanceof Error ? error : new Error('WebGL is unavailable.'),
    );
    return null;
  }

  const aspect = paperHeight / paperWidth;
  const shortSide = Math.min(1, aspect);
  const resolution = Math.round(clamp(finite(cfg.detail, 64) / 4, 8, 24));
  const columns = Math.max(8, Math.round(resolution / Math.max(1, aspect)));
  const rows = Math.max(8, Math.round(resolution * Math.min(1, aspect)));
  const seed = finite(cfg.seed, 7);
  const rng = randomSource(seed);
  const sharpness = clamp(finite(cfg.foldSharpness, 0.6), 0, 1);
  const foldTotal = Math.round(clamp(finite(cfg.foldCount, 6), 3, 16));
  const depth = clamp(finite(cfg.wrinkleDepth, 0.65), 0, 2);
  const count = (columns + 1) * (rows + 1);
  const original = new Float32Array(count * 3);
  const positions = new Float32Array(count * 3);
  const uvs = new Float32Array(count * 2);
  const indices: number[] = [];
  for (let row = 0; row <= rows; row++) {
    for (let col = 0; col <= columns; col++) {
      const index = row * (columns + 1) + col;
      const u =
        (col + (col > 0 && col < columns ? (rng() - 0.5) * 0.5 : 0)) / columns;
      const v =
        (row + (row > 0 && row < rows ? (rng() - 0.5) * 0.5 : 0)) / rows;
      original[index * 3] = u - 0.5;
      original[index * 3 + 1] = (v - 0.5) * aspect;
      uvs[index * 2] = u;
      uvs[index * 2 + 1] = v;
      if (col < columns && row < rows) {
        const a = index;
        const b = index + 1;
        const c = index + columns + 1;
        const d = c + 1;
        if (rng() > 0.5) indices.push(a, b, d, a, d, c);
        else indices.push(a, b, c, b, d, c);
      }
    }
  }
  const pathKey = JSON.stringify([
    paperWidth,
    paperHeight,
    resolution,
    foldTotal,
    sharpness,
    depth,
    seed,
  ]);
  if (pathCache?.key !== pathKey) {
    pathCache = {
      key: pathKey,
      value: createPaperPath(
        original,
        indices,
        shortSide,
        foldTotal,
        sharpness,
        depth,
        seed,
      ),
    };
  }
  const paperPath = pathCache.value;
  const lastSample = paperPath.samples.length - 1;
  const renderPositions = new Float32Array(indices.length * 3);
  const renderNormals = new Float32Array(indices.length * 3);
  const renderUvs = new Float32Array(indices.length * 2);
  const faceNormals = new Float32Array(indices.length);
  const incidentFaces: number[][] = Array.from({ length: count }, () => []);
  for (let i = 0; i < indices.length; i++) {
    const idx = at(indices, i);
    renderUvs[i * 2] = at(uvs, idx * 2);
    renderUvs[i * 2 + 1] = at(uvs, idx * 2 + 1);
    incidentFaces[idx]?.push(Math.floor(i / 3) * 3);
  }
  const geometry = new THREE.BufferGeometry();
  const positionAttribute = new THREE.BufferAttribute(
    renderPositions,
    3,
  ).setUsage(THREE.DynamicDrawUsage);
  const normalAttribute = new THREE.BufferAttribute(renderNormals, 3).setUsage(
    THREE.DynamicDrawUsage,
  );
  geometry.setAttribute('position', positionAttribute);
  geometry.setAttribute('normal', normalAttribute);
  geometry.setAttribute('uv', new THREE.BufferAttribute(renderUvs, 2));

  const grainData = new Uint8Array(128 * 128 * 4);
  for (let i = 0; i < grainData.length; i += 4) {
    const value = 100 + Math.floor(rng() * 155);
    grainData[i] = value;
    grainData[i + 1] = value;
    grainData[i + 2] = value;
    grainData[i + 3] = 255;
  }
  const grain = new THREE.DataTexture(grainData, 128, 128);
  grain.wrapS = THREE.RepeatWrapping;
  grain.wrapT = THREE.RepeatWrapping;
  grain.repeat.set(5, 5 * aspect);
  grain.magFilter = THREE.LinearFilter;
  grain.minFilter = THREE.LinearFilter;
  grain.needsUpdate = true;

  const materialOptions = {
    roughness: clamp(finite(cfg.roughness, 0.92), 0, 1),
    metalness: 0,
    bumpMap: grain,
    bumpScale: clamp(finite(cfg.paperTexture, 0.08), 0, 1) * 0.32,
    alphaTest: 0.04,
    alphaToCoverage: true,
    flatShading: false,
  };
  const frontMaterial = new THREE.MeshStandardMaterial({
    ...materialOptions,
    side: THREE.FrontSide,
  });
  const backMaterial = new THREE.MeshStandardMaterial({
    ...materialOptions,
    side: THREE.BackSide,
    color: cfg.backSrc ? '#ffffff' : cfg.paperColor,
  });
  const lighting = { value: 0 };
  for (const material of [frontMaterial, backMaterial]) {
    const stock = material === backMaterial && !cfg.backSrc;
    material.onBeforeCompile = (shader) => {
      shader.uniforms.paperLighting = lighting;
      shader.fragmentShader =
        'uniform float paperLighting;\n' + shader.fragmentShader;
      shader.fragmentShader = shader.fragmentShader.replace(
        '#include <map_fragment>',
        `
        #include <map_fragment>
        #ifdef USE_MAP
          if (vMapUv.x < 0.0 || vMapUv.x > 1.0 || vMapUv.y < 0.0 || vMapUv.y > 1.0) discard;
          ${stock ? 'diffuseColor.rgb = diffuse;' : ''}
        #endif
      `,
      );
      shader.fragmentShader = shader.fragmentShader.replace(
        '#include <opaque_fragment>',
        `
        outgoingLight = mix(diffuseColor.rgb, outgoingLight, paperLighting);
        #include <opaque_fragment>
      `,
      );
    };
    material.customProgramCacheKey = () => `paper-${stock ? 'stock' : 'print'}`;
  }
  const depthMaterial = new THREE.MeshDepthMaterial({
    depthPacking: THREE.RGBADepthPacking,
    alphaTest: 0.04,
    side: THREE.DoubleSide,
  });
  depthMaterial.onBeforeCompile = (shader) => {
    shader.fragmentShader = shader.fragmentShader.replace(
      '#include <map_fragment>',
      `
      #include <map_fragment>
      #ifdef USE_MAP
        if (vMapUv.x < 0.0 || vMapUv.x > 1.0 || vMapUv.y < 0.0 || vMapUv.y > 1.0) discard;
      #endif
    `,
    );
  };

  const sheet = new THREE.Group();
  const front = new THREE.Mesh(geometry, frontMaterial);
  const back = new THREE.Mesh(geometry, backMaterial);
  front.castShadow = cfg.shadow;
  front.receiveShadow = cfg.shadow;
  back.receiveShadow = cfg.shadow;
  front.customDepthMaterial = depthMaterial;
  sheet.add(front, back);
  const scene = new THREE.Scene();
  scene.add(sheet);
  const camera = new THREE.PerspectiveCamera(35, 1, 0.1, 10000);
  scene.add(new THREE.HemisphereLight('#ffffff', '#a4a0b0', 1.35));
  const light = new THREE.DirectionalLight(
    '#fffaf0',
    Math.max(0, finite(cfg.lightIntensity, 1.8)),
  );
  light.castShadow = cfg.shadow;
  light.shadow.mapSize.set(1024, 1024);
  light.shadow.bias = -0.0002;
  light.shadow.normalBias = 0.6;
  light.shadow.radius = 3;
  scene.add(light, light.target);
  const floorGeometry = new THREE.PlaneGeometry(1, 1);
  const floorMaterial = new THREE.ShadowMaterial({
    opacity: clamp(finite(cfg.shadowOpacity, 0.08), 0, 1),
    depthWrite: false,
  });
  const floor = new THREE.Mesh(floorGeometry, floorMaterial);
  floor.receiveShadow = true;
  floor.visible = cfg.shadow;
  scene.add(floor);
  renderer.setClearColor('#000000', 0);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.shadowMap.enabled = cfg.shadow;
  renderer.shadowMap.type = THREE.PCFShadowMap;

  const amount = spring();
  const memory = spring();
  const posX = spring();
  const posY = spring();
  const tiltX = spring();
  const tiltY = spring();
  const springs = [amount, memory, posX, posY, tiltX, tiltY];
  const raycaster = new THREE.Raycaster();
  const pointer = new THREE.Vector2();
  const plane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
  const anchor = new THREE.Vector3();
  const world = new THREE.Vector3();
  const corner = new THREE.Vector3();
  const va = new THREE.Vector3();
  const vb = new THREE.Vector3();
  const vc = new THREE.Vector3();
  const weights = new THREE.Vector3(1, 0, 0);
  let gripIndices = [Math.floor(count / 2), 0, 0];
  let viewportWidth = 1;
  let viewportHeight = 1;
  let scale = paperWidth;
  let pointerX = 0;
  let pointerY = 0;
  let lastX = 0;
  let lastY = 0;
  let lastMove = 0;
  let speedX = 0;
  let speedY = 0;
  let held = false;
  let keyboard = false;
  let pointerId: number | null = null;
  let peak = 0;
  let disposed = false;
  let ready = false;
  let inView = true;
  let hidden = false;
  let contextLost = false;
  let frame = 0;
  let lastTime = 0;
  let state: PaperCrumpleState = 'flat';
  const textures = new Set<THREE.Texture>();
  let previousAmount = -1;
  let previousMemory = -1;
  const baseRotation = THREE.MathUtils.degToRad(finite(cfg.rotation, 0));

  function publish(next: PaperCrumpleState) {
    if (next === state) return;
    state = next;
    ctx.onState(next);
  }

  function deform() {
    if (amount.value === previousAmount && memory.value === previousMemory)
      return;
    previousAmount = amount.value;
    previousMemory = memory.value;
    const fold = clamp(amount.value, 0, 1);
    const position = fold * lastSample;
    const lower = Math.floor(position);
    const upper = Math.min(lower + 1, lastSample);
    const mix = position - lower;
    const from = paperPath.samples[lower] ?? original;
    const to = paperPath.samples[upper] ?? original;
    const creaseMix = memory.value * (1 - fold);
    for (let i = 0; i < positions.length; i++) {
      const f = at(from, i);
      positions[i] =
        f +
        (at(to, i) - f) * mix +
        (at(paperPath.creased, i) - at(original, i)) * creaseMix;
    }
    for (let face = 0; face < indices.length; face += 3) {
      const a = at(indices, face) * 3;
      const b = at(indices, face + 1) * 3;
      const c = at(indices, face + 2) * 3;
      const ax = at(positions, a);
      const ay = at(positions, a + 1);
      const az = at(positions, a + 2);
      const bx = at(positions, b) - ax;
      const by = at(positions, b + 1) - ay;
      const bz = at(positions, b + 2) - az;
      const cx = at(positions, c) - ax;
      const cy = at(positions, c + 1) - ay;
      const cz = at(positions, c + 2) - az;
      const nx = by * cz - bz * cy;
      const ny = bz * cx - bx * cz;
      const nz = bx * cy - by * cx;
      const length = Math.hypot(nx, ny, nz) || 1;
      faceNormals[face] = nx / length;
      faceNormals[face + 1] = ny / length;
      faceNormals[face + 2] = nz / length;
    }
    const low = 0.88 - (1 - sharpness) * 0.18;
    for (let i = 0; i < indices.length; i++) {
      const idx = at(indices, i);
      const source = idx * 3;
      const face = Math.floor(i / 3) * 3;
      const fx = at(faceNormals, face);
      const fy = at(faceNormals, face + 1);
      const fz = at(faceNormals, face + 2);
      let nx = 0;
      let ny = 0;
      let nz = 0;
      for (const neighbor of incidentFaces[idx] ?? []) {
        const gx = at(faceNormals, neighbor);
        const gy = at(faceNormals, neighbor + 1);
        const gz = at(faceNormals, neighbor + 2);
        const weight = THREE.MathUtils.smoothstep(
          fx * gx + fy * gy + fz * gz,
          low,
          0.98,
        );
        nx += gx * weight;
        ny += gy * weight;
        nz += gz * weight;
      }
      const length = Math.hypot(nx, ny, nz) || 1;
      renderPositions[i * 3] = at(positions, source);
      renderPositions[i * 3 + 1] = at(positions, source + 1);
      renderPositions[i * 3 + 2] = at(positions, source + 2);
      renderNormals[i * 3] = nx / length;
      renderNormals[i * 3 + 1] = ny / length;
      renderNormals[i * 3 + 2] = nz / length;
    }
    positionAttribute.needsUpdate = true;
    normalAttribute.needsUpdate = true;
    geometry.computeBoundingSphere();
    geometry.computeBoundingBox();
    lighting.value = THREE.MathUtils.smoothstep(fold + memory.value, 0, 0.4);
  }

  function setCorner(bounds: THREE.Box3, i: number) {
    corner.set(
      i & 1 ? bounds.max.x : bounds.min.x,
      i & 2 ? bounds.max.y : bounds.min.y,
      i & 4 ? bounds.max.z : bounds.min.z,
    );
  }

  function placeHitTarget() {
    const bounds = geometry.boundingBox;
    if (!bounds) return;
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    for (let i = 0; i < 8; i++) {
      setCorner(bounds, i);
      corner.applyMatrix4(sheet.matrixWorld).project(camera);
      const x = ((corner.x + 1) * viewportWidth) / 2;
      const y = ((1 - corner.y) * viewportHeight) / 2;
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x);
      minY = Math.min(minY, y);
      maxY = Math.max(maxY, y);
    }
    hit.style.transform = `translate3d(${minX}px, ${minY}px, 0)`;
    hit.style.width = `${Math.max(24, maxX - minX)}px`;
    hit.style.height = `${Math.max(24, maxY - minY)}px`;
  }

  function setPointer(x: number, y: number) {
    pointer.set((x / viewportWidth) * 2 - 1, 1 - (y / viewportHeight) * 2);
    raycaster.setFromCamera(pointer, camera);
  }

  function canRun() {
    return !disposed && ready && !contextLost && inView && !hidden;
  }

  function render(time: number) {
    frame = 0;
    if (!canRun()) return;
    const dt = lastTime ? Math.min(0.04, (time - lastTime) / 1000) : 1 / 60;
    lastTime = time;
    const opts = ctx.live();
    let moving = false;
    const duration = held
      ? finite(opts.crumpleDuration, 0.55)
      : finite(opts.releaseDuration, 0.4);
    for (const s of springs) {
      const d = s === amount || s === memory ? duration : 0.42;
      moving = advance(s, dt, d, opts.reduceMotion || keyboard) || moving;
    }
    peak = Math.max(peak, amount.value);
    deform();
    sheet.rotation.set(tiltX.value, tiltY.value, baseRotation);
    if (held && !keyboard && opts.draggable) {
      anchor.set(0, 0, 0);
      for (let i = 0; i < 3; i++) {
        va.fromBufferAttribute(positionAttribute, gripIndices[i] ?? 0);
        anchor.addScaledVector(va, weights.getComponent(i));
      }
      anchor.multiplyScalar(scale).applyEuler(sheet.rotation);
      plane.constant = -anchor.z;
      setPointer(pointerX, pointerY);
      if (raycaster.ray.intersectPlane(plane, world)) {
        posX.value = posX.target = world.x - anchor.x;
        posY.value = posY.target = world.y - anchor.y;
        posX.velocity = 0;
        posY.velocity = 0;
      }
    }
    sheet.position.set(posX.value, posY.value, 0);
    sheet.updateMatrixWorld(true);
    const shadowBounds = geometry.boundingBox;
    if (shadowBounds) {
      let backZ = Infinity;
      for (let i = 0; i < 8; i++) {
        setCorner(shadowBounds, i);
        corner.applyMatrix4(sheet.matrixWorld);
        backZ = Math.min(backZ, corner.z);
      }
      floor.position.z = backZ - scale * shortSide * 0.08;
    }
    renderer.render(scene, camera);
    placeHitTarget();
    if (moving) wake();
  }

  function wake() {
    if (!frame && canRun()) frame = requestAnimationFrame(render);
  }

  function resize() {
    if (disposed) return;
    const rect = root.getBoundingClientRect();
    viewportWidth = Math.max(1, rect.width);
    viewportHeight = Math.max(1, rect.height);
    scale =
      paperWidth *
      Math.min(
        1,
        Math.max(1, viewportWidth - 48) / paperWidth,
        Math.max(1, viewportHeight - 48) / paperHeight,
      );
    sheet.scale.setScalar(scale);
    camera.aspect = viewportWidth / viewportHeight;
    camera.position.z =
      viewportHeight / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)));
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(viewportWidth, viewportHeight, false);
    const reach = Math.max(viewportWidth, viewportHeight);
    const angle = THREE.MathUtils.degToRad(finite(cfg.lightAngle, -35));
    light.position.set(
      Math.sin(angle) * reach,
      Math.cos(angle) * reach,
      reach * 4,
    );
    light.shadow.camera.left = -reach;
    light.shadow.camera.bottom = -reach;
    light.shadow.camera.right = reach;
    light.shadow.camera.top = reach;
    light.shadow.camera.near = 1;
    light.shadow.camera.far = reach * 6;
    light.shadow.camera.updateProjectionMatrix();
    floor.position.z = -scale * shortSide * 0.12;
    floor.scale.set(viewportWidth * 4, viewportHeight * 4, 1);
    root.style.setProperty('--pc-image-width', `${scale}px`);
    root.style.setProperty('--pc-image-height', `${scale * aspect}px`);
    if (!held) {
      const limitX = Math.max(0, (viewportWidth - scale) / 2 - 16);
      const limitY = Math.max(0, (viewportHeight - scale * aspect) / 2 - 16);
      posX.value = posX.target = clamp(posX.value, -limitX, limitX);
      posY.value = posY.target = clamp(posY.value, -limitY, limitY);
    }
    wake();
  }

  function finish(instant = false) {
    if (!held) return;
    const opts = ctx.live();
    held = false;
    hit.setAttribute('aria-pressed', 'false');
    hit.dataset.held = 'false';
    const captured = pointerId;
    pointerId = null;
    if (captured !== null && hit.hasPointerCapture(captured))
      hit.releasePointerCapture(captured);
    if (opts.releaseBehavior === 'stay') {
      amount.target = amount.value;
      amount.velocity = 0;
    } else {
      amount.target = 0;
      memory.target =
        opts.releaseBehavior === 'creased'
          ? Math.max(
              memory.value,
              peak * clamp(finite(opts.creaseStrength, 0.18), 0, 1),
            )
          : 0;
    }
    tiltX.target = 0;
    tiltY.target = 0;
    if (opts.returnToOrigin && opts.releaseBehavior !== 'stay') {
      posX.target = 0;
      posY.target = 0;
    } else {
      const bounds = geometry.boundingBox;
      const stay = opts.releaseBehavior === 'stay' && bounds;
      const spanX = stay ? bounds.max.x - bounds.min.x : 1;
      const spanY = stay ? bounds.max.y - bounds.min.y : aspect;
      const cos = Math.abs(Math.cos(baseRotation));
      const sin = Math.abs(Math.sin(baseRotation));
      const halfWidth = ((cos * spanX + sin * spanY) * scale) / 2;
      const halfHeight = ((sin * spanX + cos * spanY) * scale) / 2;
      const radius = Math.max(0, finite(opts.dragRadius, 180));
      const limitX = Math.min(
        radius,
        Math.max(0, viewportWidth / 2 - halfWidth - 16),
      );
      const limitY = Math.min(
        radius,
        Math.max(0, viewportHeight / 2 - halfHeight - 16),
      );
      const coast =
        !opts.reduceMotion && !keyboard && performance.now() - lastMove < 90
          ? 0.06
          : 0;
      posX.target = clamp(posX.value + speedX * coast, -limitX, limitX);
      posY.target = clamp(posY.value - speedY * coast, -limitY, limitY);
    }
    if (instant || keyboard || opts.reduceMotion) {
      for (const s of springs) advance(s, 0, 0, true);
    }
    keyboard = false;
    publish(
      opts.releaseBehavior === 'stay' && amount.target > 0.001
        ? 'crumpled'
        : memory.target > 0.001
          ? 'creased'
          : 'flat',
    );
    wake();
  }

  function reset() {
    finish(true);
    for (const s of springs) {
      s.target = 0;
      s.value = 0;
      s.velocity = 0;
    }
    peak = 0;
    publish('flat');
    wake();
  }

  function start() {
    held = true;
    peak = amount.value;
    amount.target = clamp(finite(ctx.live().crumpleAmount, 0.85), 0, 1);
    hit.setAttribute('aria-pressed', 'true');
    hit.dataset.held = 'true';
    publish('holding');
    wake();
  }

  function pointerDown(event: PointerEvent) {
    if (
      !ready ||
      ctx.live().disabled ||
      held ||
      event.button !== 0 ||
      !event.isPrimary
    )
      return;
    const rect = root.getBoundingClientRect();
    pointerX = lastX = event.clientX - rect.left;
    pointerY = lastY = event.clientY - rect.top;
    setPointer(pointerX, pointerY);
    sheet.updateMatrixWorld(true);
    const intersection = raycaster.intersectObjects([front, back], false)[0];
    const face = intersection?.face;
    if (!intersection || !face) return;
    event.preventDefault();
    hit.dataset.pointer = 'true';
    hit.focus({ preventScroll: true });
    gripIndices = [face.a, face.b, face.c];
    va.fromBufferAttribute(positionAttribute, face.a);
    vb.fromBufferAttribute(positionAttribute, face.b);
    vc.fromBufferAttribute(positionAttribute, face.c);
    THREE.Triangle.getBarycoord(
      sheet.worldToLocal(intersection.point.clone()),
      va,
      vb,
      vc,
      weights,
    );
    keyboard = false;
    pointerId = event.pointerId;
    speedX = 0;
    speedY = 0;
    lastMove = performance.now();
    hit.setPointerCapture(event.pointerId);
    start();
  }

  function pointerMove(event: PointerEvent) {
    const opts = ctx.live();
    if (!held || event.pointerId !== pointerId || !opts.draggable) return;
    const rect = root.getBoundingClientRect();
    const now = performance.now();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const dt = Math.max(0.008, (now - lastMove) / 1000);
    speedX = (x - lastX) / dt;
    speedY = (y - lastY) / dt;
    lastX = x;
    lastY = y;
    lastMove = now;
    pointerX = clamp(x, 12, viewportWidth - 12);
    pointerY = clamp(y, 12, viewportHeight - 12);
    const maxTilt = opts.reduceMotion
      ? 0
      : THREE.MathUtils.degToRad(clamp(finite(opts.dragRotation, 10), 0, 60));
    tiltX.target = clamp(speedY / 1800, -1, 1) * maxTilt;
    tiltY.target = clamp(speedX / 1800, -1, 1) * maxTilt;
    wake();
  }

  function pointerUp(event: PointerEvent) {
    if (event.pointerId === pointerId) finish();
  }

  function pointerCancel(event: PointerEvent) {
    if (event.pointerId === pointerId) finish(true);
  }

  function cancel() {
    finish(true);
  }

  function blur() {
    hit.dataset.pointer = 'false';
    cancel();
  }

  function keyDown(event: KeyboardEvent) {
    const opts = ctx.live();
    if (opts.disabled || !ready) return;
    hit.dataset.pointer = 'false';
    if (event.key === 'Escape') {
      event.preventDefault();
      reset();
      return;
    }
    if (event.key === ' ' || event.key === 'Enter') {
      event.preventDefault();
      if (event.repeat || held) return;
      keyboard = true;
      start();
      advance(amount, 0, 0, true);
      peak = Math.max(peak, amount.value);
      return;
    }
    const arrows = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'];
    if (held && keyboard && opts.draggable && arrows.includes(event.key)) {
      event.preventDefault();
      const step = event.shiftKey ? 30 : 12;
      const limit = Math.max(0, finite(opts.dragRadius, 180));
      const dx =
        event.key === 'ArrowRight'
          ? step
          : event.key === 'ArrowLeft'
            ? -step
            : 0;
      const dy =
        event.key === 'ArrowUp' ? step : event.key === 'ArrowDown' ? -step : 0;
      const limitX = Math.min(limit, viewportWidth / 3);
      const limitY = Math.min(limit, viewportHeight / 3);
      posX.target = clamp(posX.target + dx, -limitX, limitX);
      posY.target = clamp(posY.target + dy, -limitY, limitY);
      wake();
    }
  }

  function keyUp(event: KeyboardEvent) {
    if (keyboard && (event.key === ' ' || event.key === 'Enter')) {
      event.preventDefault();
      finish(true);
    }
  }

  function setInView(visible: boolean) {
    inView = visible;
    lastTime = 0;
    if (!visible) cancel();
    else wake();
  }

  function setHidden(value: boolean) {
    hidden = value;
    lastTime = 0;
    if (value) cancel();
    else wake();
  }

  function motionChange() {
    if (ctx.live().reduceMotion) {
      tiltX.target = 0;
      tiltY.target = 0;
    }
    wake();
  }

  function contextLostHandler(event: Event) {
    event.preventDefault();
    contextLost = true;
    cancel();
    ctx.onStatus('error');
    ctx.onError(new Error('The WebGL context was lost.'));
  }

  function contextRestored() {
    contextLost = false;
    if (ready) {
      ctx.onStatus('ready');
      wake();
    }
  }

  deform();
  resize();

  const loader = new THREE.TextureLoader();
  loader.setCrossOrigin('anonymous');
  function load(url: string): Promise<THREE.Texture<HTMLImageElement>> {
    return new Promise((resolve, reject) => {
      loader.load(
        url,
        (texture) => {
          if (disposed) {
            texture.dispose();
            resolve(texture);
            return;
          }
          textures.add(texture);
          texture.colorSpace = THREE.SRGBColorSpace;
          texture.anisotropy = Math.min(
            8,
            renderer.capabilities.getMaxAnisotropy(),
          );
          const image = texture.image;
          const imageAspect = image.width / image.height;
          const targetAspect = paperWidth / paperHeight;
          let rx = 1;
          let ry = 1;
          if (cfg.imageFit === 'cover') {
            if (imageAspect > targetAspect) rx = targetAspect / imageAspect;
            else ry = imageAspect / targetAspect;
          } else if (imageAspect > targetAspect)
            ry = imageAspect / targetAspect;
          else rx = targetAspect / imageAspect;
          texture.repeat.set(rx, ry);
          texture.offset.set((1 - rx) / 2, (1 - ry) / 2);
          resolve(texture);
        },
        undefined,
        () =>
          reject(
            new Error(
              `Unable to load paper image: ${url}. Remote images must allow CORS.`,
            ),
          ),
      );
    });
  }

  if (cfg.src) {
    Promise.all([
      load(cfg.src),
      cfg.backSrc ? load(cfg.backSrc) : Promise.resolve(null),
    ])
      .then(([frontTexture, backTexture]) => {
        if (disposed) return;
        if (backTexture) {
          backTexture.repeat.x *= -1;
          backTexture.offset.x = 1 - backTexture.offset.x;
        }
        frontMaterial.map = frontTexture;
        backMaterial.map = backTexture ?? frontTexture;
        depthMaterial.map = frontTexture;
        frontMaterial.needsUpdate = true;
        backMaterial.needsUpdate = true;
        depthMaterial.needsUpdate = true;
        ready = true;
        ctx.onStatus('ready');
        wake();
      })
      .catch((error: unknown) => {
        if (disposed) return;
        ctx.onStatus('error');
        ctx.onError(error instanceof Error ? error : new Error(String(error)));
      });
  } else {
    ctx.onStatus('error');
    ctx.onError(new Error('PaperCrumple requires an image src.'));
  }

  function dispose() {
    disposed = true;
    cancelAnimationFrame(frame);
    if (pointerId !== null && hit.hasPointerCapture(pointerId))
      hit.releasePointerCapture(pointerId);
    geometry.dispose();
    floorGeometry.dispose();
    frontMaterial.dispose();
    backMaterial.dispose();
    depthMaterial.dispose();
    floorMaterial.dispose();
    grain.dispose();
    for (const texture of textures) texture.dispose();
    light.shadow.dispose();
    renderer.dispose();
  }

  return {
    resize,
    setInView,
    setHidden,
    motionChange,
    reset,
    cancel,
    pointerDown,
    pointerMove,
    pointerUp,
    pointerCancel,
    keyDown,
    keyUp,
    blur,
    contextLost: contextLostHandler,
    contextRestored,
    dispose,
  };
}

import type { PaperPath, PaperSpring } from './types';

export function spring(value = 0): PaperSpring {
  return { value, target: value, velocity: 0 };
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function finite(value: number, fallback: number): number {
  return Number.isFinite(value) ? value : fallback;
}

/** Critically damped spring step. Returns true while still moving. */
export function advance(
  s: PaperSpring,
  dt: number,
  duration: number,
  instant: boolean,
): boolean {
  if (instant || duration <= 0) {
    s.value = s.target;
    s.velocity = 0;
    return false;
  }
  const omega = 8 / Math.max(0.06, duration);
  const offset = s.value - s.target;
  const term = s.velocity + omega * offset;
  const decay = Math.exp(-omega * dt);
  s.value = s.target + (offset + term * dt) * decay;
  s.velocity = (s.velocity - omega * term * dt) * decay;
  if (Math.abs(s.value - s.target) < 0.0001 && Math.abs(s.velocity) < 0.001) {
    s.value = s.target;
    s.velocity = 0;
    return false;
  }
  return true;
}

/** mulberry32 PRNG. */
export function randomSource(seed: number): () => number {
  let value = seed | 0;
  return () => {
    value |= 0;
    value = (value + 1831565813) | 0;
    let n = Math.imul(value ^ (value >>> 15), 1 | value);
    n = (n + Math.imul(n ^ (n >>> 7), 61 | n)) ^ n;
    return ((n ^ (n >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Runs the cloth-style crumple solver once and records 64 frames of vertex
 * positions plus the "creased" pose left after unfolding.
 */
export function createPaperPath(
  rest: Float32Array,
  triangles: number[],
  shortSide: number,
  density: number,
  sharpness: number,
  depth: number,
  seed: number,
): PaperPath {
  const count = rest.length / 3;
  const points = Float64Array.from(rest);
  const previous = Float64Array.from(rest);
  const before = Float64Array.from(rest);
  const edges: number[] = [];
  const hinges: number[] = [];
  const adjacency = new Map<
    number,
    { a: number; b: number; opposite: number }
  >();
  const random = randomSource(seed);
  const guides = Array.from({ length: density }, () => {
    const angle = random() * Math.PI * 2;
    return {
      x: Math.cos(angle),
      y: Math.sin(angle),
      phase: random() * Math.PI * 2,
      weight: random() * 0.6 + 0.4,
    };
  });
  const r = (i: number) => rest[i] ?? 0;
  const p = (i: number) => points[i] ?? 0;
  const tri = (i: number) => triangles[i] ?? 0;

  for (let t = 0; t < triangles.length; t += 3) {
    for (let k = 0; k < 3; k++) {
      const a = tri(t + k);
      const b = tri(t + ((k + 1) % 3));
      const opposite = tri(t + ((k + 2) % 3));
      const key = Math.min(a, b) * count + Math.max(a, b);
      const other = adjacency.get(key);
      if (!other) {
        adjacency.set(key, { a, b, opposite });
        const length = Math.hypot(
          r(a * 3) - r(b * 3),
          r(a * 3 + 1) - r(b * 3 + 1),
        );
        edges.push(a * 3, b * 3, length);
      } else {
        const c = other.opposite * 3;
        const d = opposite * 3;
        const length = Math.hypot(r(c) - r(d), r(c + 1) - r(d + 1));
        const mx = (r(c) + r(d)) * 0.5;
        const my = (r(c + 1) + r(d + 1)) * 0.5;
        let weakness = 0;
        for (const guide of guides) {
          const distance = Math.abs(
            Math.sin(
              ((mx * guide.x + my * guide.y) / shortSide) * 4 + guide.phase,
            ),
          );
          weakness = Math.max(
            weakness,
            Math.exp(-distance * distance * 80) * guide.weight,
          );
        }
        hinges.push(c, d, length, 0.12 + (1 - weakness) * 0.75);
      }
    }
  }
  const spacing = Math.sqrt((shortSide * shortSide) / count);
  const thickness = shortSide * 0.008;
  const samples: Float32Array[] = [rest.slice()];
  const frameCount = 64;
  const stepsPerFrame = 3;
  const totalSteps = frameCount * stepsPerFrame;
  let initialRadius = 0;
  for (let i = 0; i < rest.length; i += 3) {
    initialRadius = Math.max(
      initialRadius,
      Math.hypot(r(i) / 0.94, r(i + 1) / 1.02),
    );
  }
  initialRadius *= 1.02;

  function constrain(
    list: number[],
    stride: number,
    stiffness: number,
    reverse: boolean,
  ) {
    for (let n = 0; n < list.length; n += stride) {
      const edge = reverse ? list.length - stride - n : n;
      const a = list[edge] ?? 0;
      const b = list[edge + 1] ?? 0;
      const dx = p(b) - p(a);
      const dy = p(b + 1) - p(a + 1);
      const dz = p(b + 2) - p(a + 2);
      const length = Math.sqrt(dx * dx + dy * dy + dz * dz);
      if (length < 0.000001) continue;
      const weight = stride === 4 ? (list[edge + 3] ?? 1) : 1;
      const amount =
        (1 - (list[edge + 2] ?? 0) / length) * 0.5 * stiffness * weight;
      points[a] = p(a) + dx * amount;
      points[b] = p(b) - dx * amount;
      points[a + 1] = p(a + 1) + dy * amount;
      points[b + 1] = p(b + 1) - dy * amount;
      points[a + 2] = p(a + 2) + dz * amount;
      points[b + 2] = p(b + 2) - dz * amount;
    }
  }

  function separateLayers() {
    const margin = thickness * 2;
    for (let t = 0; t < triangles.length; t += 3) {
      const a = tri(t) * 3;
      const b = tri(t + 1) * 3;
      const c = tri(t + 2) * 3;
      const ax = p(a);
      const ay = p(a + 1);
      const az = p(a + 2);
      const bx = p(b) - ax;
      const by = p(b + 1) - ay;
      const bz = p(b + 2) - az;
      const cx = p(c) - ax;
      const cy = p(c + 1) - ay;
      const cz = p(c + 2) - az;
      let nx = by * cz - bz * cy;
      let ny = bz * cx - bx * cz;
      let nz = bx * cy - by * cx;
      const length = Math.hypot(nx, ny, nz);
      if (length < 0.0000001) continue;
      nx /= length;
      ny /= length;
      nz /= length;
      const minX = Math.min(ax, p(b), p(c)) - margin;
      const maxX = Math.max(ax, p(b), p(c)) + margin;
      const minY = Math.min(ay, p(b + 1), p(c + 1)) - margin;
      const maxY = Math.max(ay, p(b + 1), p(c + 1)) + margin;
      const minZ = Math.min(az, p(b + 2), p(c + 2)) - margin;
      const maxZ = Math.max(az, p(b + 2), p(c + 2)) + margin;
      const bb = bx * bx + by * by + bz * bz;
      const cc = cx * cx + cy * cy + cz * cz;
      const bc = bx * cx + by * cy + bz * cz;
      const determinant = bb * cc - bc * bc;
      if (determinant < 0.0000000001) continue;
      const restCx = (r(a) + r(b) + r(c)) / 3;
      const restCy = (r(a + 1) + r(b + 1) + r(c + 1)) / 3;
      for (let q = 0; q < points.length; q += 3) {
        if (q === a || q === b || q === c) continue;
        const qx = p(q);
        const qy = p(q + 1);
        const qz = p(q + 2);
        if (
          qx < minX ||
          qx > maxX ||
          qy < minY ||
          qy > maxY ||
          qz < minZ ||
          qz > maxZ
        )
          continue;
        const rx = r(q) - restCx;
        const ry = r(q + 1) - restCy;
        if (rx * rx + ry * ry < spacing * spacing * 6) continue;
        const dx = qx - ax;
        const dy = qy - ay;
        const dz = qz - az;
        const distance = dx * nx + dy * ny + dz * nz;
        const bA = (i: number) => before[i] ?? 0;
        const previousDistance =
          (bA(q) - bA(a)) * nx +
          (bA(q + 1) - bA(a + 1)) * ny +
          (bA(q + 2) - bA(a + 2)) * nz;
        const side = previousDistance >= 0 ? 1 : -1;
        if (distance * side >= thickness || Math.abs(distance) > margin)
          continue;
        const pb = dx * bx + dy * by + dz * bz;
        const pc = dx * cx + dy * cy + dz * cz;
        const u = (cc * pb - bc * pc) / determinant;
        const v = (bb * pc - bc * pb) / determinant;
        if (u < 0 || v < 0 || u + v > 1) continue;
        const w = 1 - u - v;
        const correction =
          (thickness * side - distance) / (1 + w * w + u * u + v * v);
        for (let axis = 0; axis < 3; axis++) {
          const normal = axis === 0 ? nx : axis === 1 ? ny : nz;
          const movement = normal * correction;
          points[q + axis] = p(q + axis) + movement;
          points[a + axis] = p(a + axis) - movement * w;
          points[b + axis] = p(b + axis) - movement * u;
          points[c + axis] = p(c + axis) - movement * v;
        }
      }
    }
  }

  for (let step = 1; step <= totalSteps; step++) {
    const progress = step / totalSteps;
    const compression = progress * progress * (3 - 2 * progress);
    const radius =
      initialRadius * (1 - compression) +
      shortSide * (0.19 - depth * 0.025) * compression;
    before.set(points);
    for (let i = 0; i < points.length; i += 3) {
      const x = r(i) / shortSide;
      const y = r(i + 1) / shortSide;
      let buckle = 0;
      for (const guide of guides) {
        buckle +=
          Math.sin((x * guide.x + y * guide.y) * 5 + guide.phase) *
          guide.weight;
      }
      for (let axis = 0; axis < 3; axis++) {
        const velocity = (p(i + axis) - (previous[i + axis] ?? 0)) * 0.55;
        previous[i + axis] = p(i + axis);
        points[i + axis] =
          p(i + axis) + clamp(velocity, -spacing * 0.15, spacing * 0.15);
      }
      points[i + 2] =
        p(i + 2) +
        (buckle / density) * shortSide * 0.0007 * Math.sin(progress * Math.PI);
    }
    for (let pass = 0; pass < 18; pass++) {
      constrain(hinges, 4, 0.45 * (1 - sharpness * 0.4), pass % 2 === 0);
      for (let i = 0; i < points.length; i += 3) {
        const x = p(i) / 0.94;
        const y = p(i + 1) / 1.02;
        const z = p(i + 2) / 0.86;
        const distance = Math.hypot(x, y, z);
        if (distance > radius) {
          const push = (1 - radius / distance) * 0.55;
          points[i] = p(i) - p(i) * push;
          points[i + 1] = p(i + 1) - p(i + 1) * push;
          points[i + 2] = p(i + 2) - p(i + 2) * push;
        }
      }
      constrain(edges, 3, 1, pass % 2 !== 0);
      if (pass === 8 || pass === 17) separateLayers();
    }
    for (let h = 0; h < hinges.length; h += 4) {
      const a = hinges[h] ?? 0;
      const b = hinges[h + 1] ?? 0;
      const rest2 = hinges[h + 2] ?? 0;
      const length = Math.hypot(
        p(a) - p(b),
        p(a + 1) - p(b + 1),
        p(a + 2) - p(b + 2),
      );
      if (length < rest2 * 0.86)
        hinges[h + 2] = rest2 + (length - rest2) * 0.12;
    }
    if (step % stepsPerFrame === 0) samples.push(Float32Array.from(points));
  }
  const folded = Float64Array.from(points);
  for (let step = 1; step <= 80; step++) {
    const t = step / 80;
    const unfold = t * t * (3 - 2 * t);
    for (let pass = 0; pass < 12; pass++) {
      for (let i = 0; i < points.length; i++) {
        const f = folded[i] ?? 0;
        const target = f + (r(i) - f) * unfold;
        points[i] = p(i) + (target - p(i)) * (i % 3 === 2 ? 0.04 : 0.22);
      }
      constrain(hinges, 4, 0.7, pass % 2 === 0);
      constrain(edges, 3, 1, pass % 2 !== 0);
    }
  }
  return { samples, creased: Float32Array.from(points) };
}

/** Lifecycle state reported through the `state-change` event. */
export type PaperCrumpleState = 'flat' | 'holding' | 'crumpled' | 'creased';

/** What the sheet does when the hold ends. */
export type PaperCrumpleRelease = 'stay' | 'restore' | 'creased';

/** How the image texture is fitted onto the sheet. */
export type PaperCrumpleImageFit = 'cover' | 'contain';

/** Loading state of the WebGL scene. */
export type PaperCrumpleStatus = 'loading' | 'ready' | 'error';

/**
 * Props for the PaperCrumple registry component.
 */
export interface PaperCrumpleProps {
  /** Image URL. PNG transparency is kept. Remote hosts must allow CORS. */
  src: string;
  /** Image description for the fallback image and the hold control. */
  alt?: string;
  /** Optional image printed on the back. Otherwise the back uses `paperColor`. */
  backSrc?: string;
  /** Unfolded paper width in px. Scales down to fit the stage with a 24px inset. */
  width?: number;
  /** Unfolded paper height in px. Sets the sheet aspect ratio. */
  height?: number;
  /** Stage height in px, including room to drag. */
  sceneHeight?: number;
  /** `cover` crops the texture; `contain` keeps the whole image. */
  imageFit?: PaperCrumpleImageFit;
  /** Freeze the crumple, unfold fully, or unfold with lasting creases. */
  releaseBehavior?: PaperCrumpleRelease;
  /** Maximum fold amount while held, 0 (flat) to 1 (fully crumpled). */
  crumpleAmount?: number;
  /** Approximate settling time in seconds while holding. */
  crumpleDuration?: number;
  /** Approximate unfolding time in seconds. */
  releaseDuration?: number;
  /** Number of crease guides in the paper solver, 3 to 16. */
  foldCount?: number;
  /** Blend from rounded wrinkles (0) to angular creases (1). */
  foldSharpness?: number;
  /** Compression depth, 0 to 2. */
  wrinkleDepth?: number;
  /** Residual relief, 0 to 1, for the `creased` release mode. */
  creaseStrength?: number;
  /** Color of the unprinted back of the sheet. */
  paperColor?: string;
  /** Material roughness, 0 (smooth) to 1 (matte). */
  roughness?: number;
  /** Paper-grain bump strength, 0 to 1. */
  paperTexture?: number;
  /** Directional light strength. */
  lightIntensity?: number;
  /** Key light direction in degrees. 0 shines from above. */
  lightAngle?: number;
  /** Self-shadowing plus a soft drop shadow. */
  shadow?: boolean;
  /** Opacity of the cast and drop shadows, 0 to 1. */
  shadowOpacity?: number;
  /** Move the sheet while held. */
  draggable?: boolean;
  /** Maximum tilt in degrees while dragging. */
  dragRotation?: number;
  /** Maximum resting offset on each axis, in px. */
  dragRadius?: number;
  /** `restore` and `creased` return the sheet to the center. */
  returnToOrigin?: boolean;
  /** Initial sheet rotation in degrees. */
  rotation?: number;
  /** Seed for a repeatable fold and grain arrangement. */
  seed?: number;
  /** Simulation detail. Higher values add smaller folds. */
  detail?: number;
  /** Disable input and finish any active hold. */
  disabled?: boolean;
  /** Change this value to reset position, crumple and creases. */
  resetKey?: number | string;
  /** Extra classes for the stage. */
  class?: string;
}

/** Live options the engine reads on every frame. */
export interface PaperCrumpleLiveOptions {
  releaseBehavior: PaperCrumpleRelease;
  crumpleAmount: number;
  crumpleDuration: number;
  releaseDuration: number;
  creaseStrength: number;
  draggable: boolean;
  dragRotation: number;
  dragRadius: number;
  returnToOrigin: boolean;
  disabled: boolean;
  reduceMotion: boolean;
}

/** Structural options; a change rebuilds the scene. */
export interface PaperCrumpleSceneOptions {
  src: string;
  backSrc: string;
  width: number;
  height: number;
  imageFit: PaperCrumpleImageFit;
  foldCount: number;
  foldSharpness: number;
  wrinkleDepth: number;
  paperColor: string;
  roughness: number;
  paperTexture: number;
  lightIntensity: number;
  lightAngle: number;
  shadow: boolean;
  shadowOpacity: number;
  rotation: number;
  seed: number;
  detail: number;
}

/** Elements and callbacks handed to the engine. */
export interface PaperCrumpleEngineContext {
  root: HTMLDivElement;
  canvas: HTMLCanvasElement;
  hit: HTMLButtonElement;
  scene: PaperCrumpleSceneOptions;
  live: () => PaperCrumpleLiveOptions;
  onStatus: (status: PaperCrumpleStatus) => void;
  onState: (state: PaperCrumpleState) => void;
  onError: (error: Error) => void;
}

/** Imperative handle returned by the engine. */
export interface PaperCrumpleEngine {
  resize: () => void;
  setInView: (visible: boolean) => void;
  setHidden: (hidden: boolean) => void;
  motionChange: () => void;
  reset: () => void;
  cancel: () => void;
  pointerDown: (event: PointerEvent) => void;
  pointerMove: (event: PointerEvent) => void;
  pointerUp: (event: PointerEvent) => void;
  pointerCancel: (event: PointerEvent) => void;
  keyDown: (event: KeyboardEvent) => void;
  keyUp: (event: KeyboardEvent) => void;
  blur: () => void;
  contextLost: (event: Event) => void;
  contextRestored: () => void;
  dispose: () => void;
}

/** Spring state used by the critically damped integrator. */
export interface PaperSpring {
  value: number;
  target: number;
  velocity: number;
}

/** Precomputed crumple animation: per-frame vertex samples plus the creased rest pose. */
export interface PaperPath {
  samples: Float32Array[];
  creased: Float32Array;
}
